        'spark'=>'<path d="m12 3 2.3 6.7L21 12l-6.7 2.3L12 21l-2.3-6.7L3 12l6.7-2.3L12 3Z"/>',
        'plug'=>'<path d="M9 3v5m6-5v5M7 8h10v3a5 5 0 0 1-10 0V8Zm5 8v5"/>',
        'book'=>'<path d="M12 5v16M3 3l9 2 9-2v16l-9 2-9-2V3Z"/>',
        'arrow'=>'<path d="M5 12h14m-6-6 6 6-6 6"/>',
        'play'=>'<path d="m9 5 11 7-11 7V5Z"/>',
        'plus'=>'<path d="M12 5v14M5 12h14"/>',
        'clock'=>'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
        'check'=>'<path d="m5 12 4 4L19 6"/>',
        'chevron'=>'<path d="m9 6 6 6-6 6"/>',
        'refresh'=>'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 7a7 7 0 0 1 12-1l2 6M4 12l2 6a7 7 0 0 0 12-1"/>',
        'external'=>'<path d="M14 3h7v7M21 3 10 14M10 3H4v17h17v-6"/>',
        'download'=>'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>'
    ];
    return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'.($paths[$name]??$paths['spark']).'</svg>';
}
